import { buildMedia, parseTrackLines, checkSrcset, parseSrcset } from '@fodt/media-embed-builder';

const video = buildMedia({
  kind: 'video',
  src: 'brave.webm',
  tracks: 'brave.en.vtt | subtitles | en | English',
  controls: true,
});
video?.html;
// <video src="brave.webm" controls>
//   <track kind="subtitles" src="brave.en.vtt" srclang="en" label="English">
// </video>

const image = buildMedia({
  kind: 'image',
  src: 'photo-800.jpg',
  srcset: 'photo-400.jpg 400w, photo-800.jpg 800w',
  sizes: '(max-width: 600px) 100vw, 800px',
  alt: 'A harbour at dusk',
  width: '800',
  height: '533',
});
image?.html;
// <img src="photo-800.jpg" srcset="photo-400.jpg 400w, photo-800.jpg 800w" sizes="(max-width: 600px) 100vw, 800px" alt="A harbour at dusk" width="800" height="533">

checkSrcset(parseSrcset('a.png 100w, b.png 2x', 'Srcset'), 'Srcset', { sizesPresent: true });
// throws MarkupError: Srcset: width descriptors (such as 400w) and pixel density descriptors (such as 2x) cannot be mixed
